class LegacyAnalytics:
    def __init__(self):
        self.calls = []

    def start_session(self, session_id):
        self.calls.append(('start', session_id))

    def log_event(self, session_id, event):
        self.calls.append(('event', session_id, event))


class AnalyticsAdapter:
    def __init__(self, legacy, session_id):
        self.legacy = legacy
        self.session_id = session_id
        self.started = False

    def track(self, event):
        if not self.started:
            self.legacy.start_session(self.session_id)
            self.started = True
        self.legacy.log_event(self.session_id, event)
